{
  "name": "@sharath_huddar/opencode-claude-usage",
  "version": "0.1.1",
  "description": "OpenCode TUI plugin: live Claude plan usage (5h / weekly limits) in the sidebar while a Claude Agent model is selected.",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/SharathHuddar/opencode-claude-usage.git"
  },
  "homepage": "https://github.com/SharathHuddar/opencode-claude-usage#readme",
  "bugs": {
    "url": "https://github.com/SharathHuddar/opencode-claude-usage/issues"
  },
  "type": "module",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "claude",
    "usage"
  ],
  "os": [
    "darwin"
  ],
  "exports": {
    "./tui": "./dist/tui.js"
  },
  "files": [
    "dist",
    "src",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "bun scripts/build.ts",
    "prepack": "npm run build",
    "typecheck": "tsc --noEmit"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.3.0",
    "@opentui/core": ">=0.8.4",
    "@opentui/solid": ">=0.8.4",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opencode/plugin": "2.3.2",
    "@opencode/theme": "2.3.2",
    "@opentui/core": "^0.9.2",
    "@opentui/solid": "^0.9.2",
    "@types/node": "^24.0.0",
    "bun": "^1.4.4",
    "solid-js": "^1.9.0",
    "typescript": "^5.9.0"
  },
  "publishConfig": {
    "access": "public"
  }
}
